-- Clinicorp: conector por configuração (src/erp/conectores/clinicorp.json; docs/erps/clinicorp.md). Entra em
-- homologação. A configuração pode ser editada depois pela Central (cada gravação sobe a versão).
-- test/clinicorp.test.ts confere que o JSON abaixo é o mesmo do arquivo.
INSERT INTO conectores (slug, nome, artigo, tipo, situacao, observacao, config) VALUES
  ('clinicorp', 'Clinicorp', 'a', 'configuracao', 'homologacao',
   'Clinicorp: Basic (ID de acesso + Token API), ID da clínica. Sem convênio, preço e cobrança na API.',
   '{"versao":1,"base_url":"https://api.clinicorp.com/rest/v1","autenticacao":{"tipo":"basic","usuario":"usuario","senha":"token"},"idempotencia_header":null,"campos":[{"chave":"usuario","rotulo":"ID de acesso (Usuário API)","tipo":"texto","obrigatorio":true,"ajuda":"Clinicorp: Gerenciar Assinatura → Acesso Externo e Integrações → Integrações → Usuário API."},{"chave":"token","rotulo":"Token API","tipo":"segredo","obrigatorio":true,"ajuda":"Mesmo lugar: Token API."},{"chave":"clinica_id","rotulo":"ID da clínica","tipo":"texto","obrigatorio":true,"ajuda":"O número da clínica (unidade) na Clinicorp. A implantação pode consultar em GET /business/list."}],"especificacao":false,"rotas":{"GET /status":{"metodo":"GET","caminho":"/professional/list_all_professionals","resposta":{"status":"ok"}},"GET /profissionais":{"metodo":"GET","caminho":"/professional/list_all_professionals","resposta":{"dados":{"$lista":"{{$raiz}}","$se":"{{$.name}}","$item":{"id":"{{$.id | texto}}","nome":"{{$.name}}"}}}},"GET /especialidades":{"metodo":"GET","caminho":"/procedures/list_specialties","query":{"subscriber_id":"{{cred.usuario}}"},"resposta":{"dados":{"$lista":"{{$raiz}}","$se":"{{$.Description}}","$item":{"id":"{{$.id | texto}}","nome":"{{$.Description}}"}}}},"GET /profissionais/{id}/dias-disponiveis":{"metodo":"GET","caminho":"/business/list_available_times","query":{"professionalId":"{{path.id}}","clinicId":"{{cred.clinica_id}}","fromDate":"{{query.de | data:YYYYMMDD}}","toDate":"{{query.ate | data:YYYYMMDD}}"},"resposta":{"dias":{"$lista":"{{$raiz}}","$se":"{{$.slots}}","$item":{"data":"{{$.date | data_iso:YYYYMMDD}}"}}}},"GET /profissionais/{id}/horarios-disponiveis":{"metodo":"GET","caminho":"/business/list_available_times","query":{"professionalId":"{{path.id}}","clinicId":"{{cred.clinica_id}}","fromDate":"{{query.data | data:YYYYMMDD}}","toDate":"{{query.data | data:YYYYMMDD}}"},"resposta":{"horarios":{"$lista":"{{$raiz[0].slots}}","$item":{"inicio":"{{$.fromTime | hora_curta}}","slot_id":"{{$.toTime | hora_curta}}"}}}},"GET /pacientes":{"metodo":"GET","caminho":"/patient/get","query":{"subscriber_id":"{{cred.usuario}}","OtherDocumentId":"{{query.cpf}}","Phone":"{{query.telefone}}"},"resposta":{"dados":[{"id":"{{$.PatientId | texto}}","nome":"{{$.Name}}","nascimento":"{{$.BirthDate | data_iso}}","telefone":"{{$.Phone | sem_ddi}}","cpf":"{{$.OtherDocumentId | digitos}}"}]}},"POST /pacientes":{"metodo":"POST","caminho":"/patient/create","corpo":{"subscriber_id":"{{cred.usuario}}","Name":"{{corpo.nome}}","BirthDate":"{{corpo.nascimento}}","MobilePhone":"{{corpo.telefones[0].numero | sem_ddi}}","OtherDocumentId":"{{corpo.cpf | digitos}}"},"resposta":{"id":"{{$.PatientId | texto}}"}},"GET /pacientes/{id}/agendamentos":{"metodo":"GET","caminho":"/appointment/list","query":{"subscriber_id":"{{cred.usuario}}","patientId":"{{path.id}}","from":"{{hoje}}","to":"{{hoje | mais_dias:180}}"},"resposta":{"dados":{"$lista":"{{$raiz}}","$se":["{{$.ItemType}}","APPOINTMENT"],"$exceto":[["{{$.Canceled}}","X"],["{{$.Deleted}}","X"]],"$item":{"id":"{{$.id | texto}}","inicio":"{{$.AtomicDate | data_iso:YYYYMMDD}}T{{$.fromTime | hora_curta}}","status":"agendado"}}}},"GET /agenda":{"metodo":"GET","caminho":"/appointment/list","query":{"subscriber_id":"{{cred.usuario}}","businessId":"{{cred.clinica_id}}","from":"{{query.data}}","to":"{{query.data}}"},"resposta":{"itens":{"$lista":"{{$raiz}}","$se":[["{{$.ItemType}}","APPOINTMENT"],["{{$.Dentist_PersonId | texto}}","{{$req.query.profissional_id}}"]],"$exceto":[["{{$.Deleted}}","X"]],"$item":{"tipo":"agendamento","inicio":"{{$.fromTime | hora_curta}}","agendamento":{"id":"{{$.id | texto}}","status":"{{$.Canceled | mapa:X=desmarcado}}","paciente":{"nome":"{{$.PatientName}}","telefone":"{{$.MobilePhone | digitos | sem_ddi}}"},"observacao":"{{$.Notes}}"}}}}},"GET /convenios":{"fixo":{"dados":[{"id":"0","nome":"Particular"}]}},"GET /procedimentos":{"metodo":"GET","caminho":"/procedures/list","resposta":{"dados":{"$lista":"{{$raiz}}","$se":"{{$.ProcedureName}}","$item":{"id":"{{$.id | texto}}","nome":"{{$.ProcedureName}}","tipo":"consulta"}}}},"POST /agendamentos":{"metodo":"POST","caminho":"/appointment/create_appointment_by_api","corpo":{"Patient_PersonId":"{{corpo.paciente_id | numero}}","date":"{{corpo.data}}T03:00:00.000Z","fromTime":"{{corpo.horario}}","toTime":"{{corpo.slot_id}}","Clinic_BusinessId":"{{cred.clinica_id | numero}}","Dentist_PersonId":"{{corpo.profissional_id | numero}}"},"resposta":{"id":"{{$raiz[0].id | texto}}","status":"{{$raiz[0].Status}}"}},"POST /agendamentos/{id}/cancelar":{"metodo":"POST","caminho":"/appointment/cancel_appointment","corpo":{"subscriber_id":"{{cred.usuario}}","id":"{{path.id}}"}},"POST /agendamentos/{id}/status":{"se":["{{corpo.status}}","confirmado"],"metodo":"POST","caminho":"/appointment/confirm_appointment","corpo":{"subscriber_id":"{{cred.usuario}}","id":"{{path.id | numero}}"}},"GET /confirmacoes/pendentes":{"metodo":"GET","caminho":"/appointment/list","query":{"subscriber_id":"{{cred.usuario}}","businessId":"{{cred.clinica_id}}","from":"{{query.data_consulta}}","to":"{{query.data_consulta}}"},"resposta":{"dados":{"$lista":"{{$raiz}}","$se":["{{$.ItemType}}","APPOINTMENT"],"$exceto":[["{{$.Canceled}}","X"],["{{$.Deleted}}","X"]],"$item":{"agendamento_id":"{{$.id | texto}}","inicio":"{{$.AtomicDate | data_iso:YYYYMMDD}}T{{$.fromTime | hora_curta}}","paciente":{"nome":"{{$.PatientName}}","telefone_whatsapp":"{{$.MobilePhone | digitos}}"}}}}},"POST /confirmacoes/enviadas":{"fixo":{"ok":true}}},"erros":{"credencial":[{"status":[401,403]}],"nao_encontrado":[{"status":[400,404],"caminho":"{{$.Message}}","contem":"encontrad"}],"mensagem":"{{$.Message}}"}}'::jsonb)
ON CONFLICT (slug) DO NOTHING;
